/// The screen itself: a frame, corner markers, colour bars and a crosshair.
///
/// Deliberately made of primitives only -- no text, no assets -- so what is wrong is obvious: a missing
/// frame is an address-window fault, a shifted frame is an offset, wrong colours are the colour order,
/// and white where black was asked for is the inversion.
fn draw_diagnostic(display: &mut panel::DisplayDriver) {
    let width = panel::DRAW_WIDTH as i32;
    let height = panel::DRAW_HEIGHT as i32;
    display.clear(Rgb565::BLACK).expect("the panel accepted the clear");

    let frame = Rectangle::new(Point::new(0, 0), Size::new(width as u32, height as u32))
        .into_styled(PrimitiveStyle::with_stroke(Rgb565::WHITE, 2));
    frame.draw(display).expect("the frame was drawn");

    // Corner markers, 20 px squares: the top-left one being missing or doubled is the classic sign of a
    // display offset that the glass needs and the driver was not told about.
    for (x, y) in [
        (2, 2),
        (width - 22, 2),
        (2, height - 22),
        (width - 22, height - 22),
    ] {
        Rectangle::new(Point::new(x, y), Size::new(20, 20))
            .into_styled(PrimitiveStyle::with_fill(Rgb565::CSS_RED))
            .draw(display)
            .expect("a corner marker was drawn");
    }

    // The three primary bars, left to right: red, green and blue in that order is what a correct colour
    // order and a normal polarity look like on this glass.
    let bar_w = (width / 3) as u32;
    let bar_h = (height / 6) as u32;
    for (index, colour) in [Rgb565::CSS_RED, Rgb565::CSS_GREEN, Rgb565::CSS_BLUE].into_iter().enumerate() {
        Rectangle::new(
            Point::new((index as i32) * bar_w as i32, height / 2 - bar_h as i32 / 2),
            Size::new(bar_w, bar_h),
        )
        .into_styled(PrimitiveStyle::with_fill(colour))
        .draw(display)
        .expect("a colour bar was drawn");
    }

    // A crosshair through the middle: it is what makes a mirroring fault legible, because the shorter arm
    // ends up on the wrong side.
    Line::new(Point::new(width / 2 - 40, height / 2), Point::new(width / 2 + 40, height / 2))
        .into_styled(PrimitiveStyle::with_stroke(Rgb565::WHITE, 1))
        .draw(display)
        .expect("the crosshair was drawn");
    Line::new(Point::new(width / 2, height / 2 - 60), Point::new(width / 2, height / 2 - 10))
        .into_styled(PrimitiveStyle::with_stroke(Rgb565::WHITE, 1))
        .draw(display)
        .expect("the long arm was drawn");
}

/// The sketch's entry point.
#[embassy_executor::main(executor = "embassy_rp::executor::Executor", entry = "cortex_m_rt::entry")]
async fn main(spawner: Spawner) {
    let mut state = setup(spawner).await;

    // A blinking square in the top-right corner: a still picture cannot tell "the firmware stopped" from
    // "the panel stopped", and this can.
    let mut on = false;
    loop {
        let colour = if on { Rgb565::CSS_YELLOW } else { Rgb565::BLACK };
        Rectangle::new(
            Point::new(panel::DRAW_WIDTH as i32 - 32, 8),
            Size::new(16, 16),
        )
        .into_styled(PrimitiveStyle::with_fill(colour))
        .draw(&mut state.hardware.display)
        .expect("the heartbeat was drawn");
        on = !on;
        info!("panel diagnostic: heartbeat {} (last frame {} ms)", on, state.paint_ms);
        Timer::after(Duration::from_millis(500)).await;
    }
}
